#include <bits/stdc++.h>
using namespace std;
class Solution {public:long long sellingWood(int m,int n,vector<vector<int>>& prices){vector<vector<long long>> dp(m+1,vector<long long>(n+1));for(auto& p:prices)dp[p[0]][p[1]]=max(dp[p[0]][p[1]],(long long)p[2]);for(int h=1;h<=m;++h)for(int w=1;w<=n;++w){for(int x=1;x<=h/2;++x)dp[h][w]=max(dp[h][w],dp[x][w]+dp[h-x][w]);for(int y=1;y<=w/2;++y)dp[h][w]=max(dp[h][w],dp[h][y]+dp[h][w-y]);}return dp[m][n];}};
